<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>晨跃健身江湾店 · 本周团课预约</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; background: #f4f6f8; color: #222; }
  header { background: #1f6f54; color: #fff; padding: 16px; }
  header h1 { margin: 0 0 4px; font-size: 20px; }
  header p { margin: 0; font-size: 13px; opacity: .9; }
  .toolbar { padding: 12px 16px; background: #fff; border-bottom: 1px solid #ddd; }
  .toolbar label { font-weight: 600; margin-right: 8px; }
  #type-filter { padding: 6px 10px; font-size: 15px; }
  #notice { margin: 12px 16px; padding: 10px 14px; border-radius: 8px; background: #eef3ff; border: 1px solid #c4d2f5; min-height: 1.2em; }
  #notice.ok { background: #e8f7ee; border-color: #b3e2c5; color: #1c6b3c; }
  #notice.err { background: #fdeeee; border-color: #f0c2c2; color: #a03030; }
  main { padding: 8px 16px 32px; display: grid; gap: 12px; max-width: 640px; margin: 0 auto; }
  .card { background: #fff; border: 1px solid #e0e4e8; border-radius: 10px; padding: 14px 16px; display: flex; justify-content: space-between; align-items: center; gap: 12px; }
  .card h2 { margin: 0 0 6px; font-size: 17px; }
  .card .meta { font-size: 14px; color: #555; line-height: 1.5; }
  .card button { font-size: 15px; padding: 10px 18px; border-radius: 8px; border: 1px solid #1f6f54; background: #1f6f54; color: #fff; cursor: pointer; }
  .card button:focus-visible { outline: 3px solid #ffb703; outline-offset: 2px; }
  .card button:disabled { background: #c9ced3; border-color: #c9ced3; color: #666; cursor: not-allowed; }
  .card button.booked { background: #2b7a4b; }
</style>
</head>
<body>
<header>
  <h1>晨跃健身江湾店 · 本周团课预约</h1>
  <p>周 20281009</p>
</header>
<div class="toolbar">
  <label for="type-filter">课程类型</label>
  <select id="type-filter">
    <option value="all">全部</option>
    <option value="搏击">搏击</option>
    <option value="瑜伽">瑜伽</option>
    <option value="单车">单车</option>
  </select>
</div>
<div id="notice" role="status" aria-live="polite"></div>
<main id="list"></main>
<script>
(function () {
  var DATA = {
    week_id: "20281009",
    courses: [
      { id: "C283", title: "搏击·力量", type: "搏击", date: "2028-10-09", start: "15:45", end: "16:30", coach: "王珂", remaining: 6 },
      { id: "C800", title: "瑜伽·舒展", type: "瑜伽", date: "2028-10-11", start: "12:00", end: "13:00", coach: "林安", remaining: 0 },
      { id: "C254", title: "瑜伽·力量", type: "瑜伽", date: "2028-10-10", start: "15:00", end: "15:45", coach: "李岚", remaining: 4 },
      { id: "C725", title: "单车·进阶", type: "单车", date: "2028-10-09", start: "06:00", end: "06:30", coach: "沈禾", remaining: 5 },
      { id: "C647", title: "单车·舒展", type: "单车", date: "2028-10-12", start: "09:30", end: "10:30", coach: "赵晴", remaining: 1 },
      { id: "C649", title: "单车·入门", type: "单车", date: "2028-10-11", start: "13:30", end: "14:30", coach: "陈星", remaining: 0 },
      { id: "C501", title: "瑜伽·进阶", type: "瑜伽", date: "2028-10-09", start: "15:00", end: "15:45", coach: "陈星", remaining: 7 },
      { id: "C839", title: "搏击·进阶", type: "搏击", date: "2028-10-09", start: "15:00", end: "15:45", coach: "赵晴", remaining: 4 },
      { id: "C209", title: "瑜伽·力量", type: "瑜伽", date: "2028-10-12", start: "08:00", end: "09:00", coach: "周宁", remaining: 3 },
      { id: "C972", title: "单车·进阶", type: "单车", date: "2028-10-09", start: "15:00", end: "15:45", coach: "周宁", remaining: 6 }
    ]
  };

  var KEY = "chenyue-" + DATA.week_id;
  var courses = DATA.courses;
  var byId = {};
  courses.forEach(function (c) { byId[c.id] = c; });

  var booked = [];
  var storageOk = true;
  try {
    var raw = window.localStorage.getItem(KEY);
    if (raw != null) {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        var seen = {};
        parsed.forEach(function (id) {
          if (typeof id === "string" && !seen[id] && byId[id] && byId[id].remaining > 0) {
            seen[id] = true;
            booked.push(id);
          }
        });
      }
    }
  } catch (e) { storageOk = false; booked = []; }

  function save() {
    if (!storageOk) return;
    try { window.localStorage.setItem(KEY, JSON.stringify(booked)); } catch (e) {}
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }
  function remainingOf(c) { return c.remaining - (isBooked(c.id) ? 1 : 0); }

  function overlaps(a, b) {
    if (a.date !== b.date) return false;
    return a.start < b.end && b.start < a.end;
  }

  var notice = document.getElementById("notice");
  function show(msg, kind) {
    notice.textContent = msg;
    notice.className = kind || "";
  }

  var list = document.getElementById("list");
  var filter = document.getElementById("type-filter");
  var buttons = {};

  function render() {
    var val = filter.value;
    list.innerHTML = "";
    buttons = {};
    courses.forEach(function (c) {
      if (val !== "all" && c.type !== val) return;
      var card = document.createElement("section");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);
      var left = document.createElement("div");
      var h = document.createElement("h2");
      h.textContent = c.title;
      left.appendChild(h);
      var meta = document.createElement("div");
      meta.className = "meta";
      meta.textContent = "类型：" + c.type + "　日期：" + c.date + "　时间：" + c.start + "–" + c.end + "　教练：" + c.coach;
      left.appendChild(meta);
      var remLine = document.createElement("div");
      remLine.className = "meta";
      remLine.appendChild(document.createTextNode("剩余名额 "));
      var rem = document.createElement("span");
      rem.setAttribute("data-remaining", "");
      rem.textContent = String(remainingOf(c));
      remLine.appendChild(rem);
      remLine.appendChild(document.createTextNode(" 人"));
      left.appendChild(remLine);
      card.appendChild(left);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var r = remainingOf(c);
      if (isBooked(c.id)) {
        btn.textContent = "已预约";
        btn.className = "booked";
        btn.disabled = true;
      } else if (r <= 0) {
        btn.textContent = "已满员";
        btn.disabled = true;
      } else {
        btn.textContent = "预约";
        btn.addEventListener("click", function () { book(c.id); });
      }
      buttons[c.id] = btn;
      card.appendChild(btn);
      list.appendChild(card);
    });
  }

  function book(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) { show("已预约过这节课", ""); return; }
    if (remainingOf(c) <= 0) { show("该课程已满员", "err"); return; }
    var conflict = null;
    for (var i = 0; i < booked.length; i++) {
      var other = byId[booked[i]];
      if (other && overlaps(c, other)) { conflict = other; break; }
    }
    if (conflict) { show("该时段已有预约", "err"); return; }
    booked.push(id);
    save();
    render();
    show("预约成功", "ok");
  }

  filter.addEventListener("change", render);
  render();
  show("", "");
})();
</script>
</body>
</html>

