<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>岚动训练湖畔店 · 本周团课预约</title>
<style>
  :root { --accent:#0b6bcb; --ok:#0a7d33; --err:#b3261e; }
  * { box-sizing:border-box; }
  body { font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif; margin:0; background:#f4f6f9; color:#1c2430; }
  header { background:#12233d; color:#fff; padding:16px 20px; }
  header h1 { margin:0; font-size:20px; }
  header p { margin:4px 0 0; font-size:13px; opacity:.8; }
  main { max-width:720px; margin:0 auto; padding:16px; }
  .filter-row { display:flex; align-items:center; gap:8px; margin-bottom:14px; }
  .filter-row label { font-size:14px; font-weight:600; }
  select { font-size:15px; padding:8px 10px; border:1px solid #b9c2cf; border-radius:8px; background:#fff; }
  select:focus, button:focus-visible { outline:3px solid #7db4ee; outline-offset:2px; }
  #notice { min-height:22px; padding:10px 12px; border-radius:8px; margin-bottom:14px; font-size:14px; }
  #notice.ok { background:#e2f3e6; color:var(--ok); }
  #notice.err { background:#fbe9e7; color:var(--err); }
  .card { background:#fff; border:1px solid #dde3ec; border-radius:12px; padding:14px 16px; margin-bottom:12px; display:flex; justify-content:space-between; align-items:center; gap:12px; }
  .card h2 { margin:0 0 6px; font-size:17px; }
  .meta { font-size:13px; color:#4a5568; line-height:1.6; }
  .right { text-align:right; flex-shrink:0; }
  .remain { font-size:13px; color:#4a5568; margin-bottom:8px; }
  button[data-book] { font-size:15px; padding:9px 18px; border-radius:8px; border:none; background:var(--accent); color:#fff; cursor:pointer; }
  button[data-book]:disabled { background:#9aa5b1; cursor:not-allowed; }
  button[data-book].booked { background:var(--ok); }
</style>
</head>
<body>
<header>
  <h1>岚动训练 · 湖畔店</h1>
  <p>本周团课自助预约（20281016 周）</p>
</header>
<main>
  <div class="filter-row">
    <label for="type-filter">课程类型</label>
    <select id="type-filter">
      <option value="all">全部</option>
      <option value="杠铃">杠铃</option>
      <option value="拉伸">拉伸</option>
      <option value="舞蹈">舞蹈</option>
    </select>
  </div>
  <div id="notice" role="status" aria-live="polite"></div>
  <div id="course-list"></div>
</main>
<script>
(function () {
  var DATA = {
    "week_id": "20281016",
    "venue": "岚动训练湖畔店",
    "courses": [
      {"id":"C575","title":"杠铃·进阶","type":"杠铃","date":"2028-10-18","start":"13:30","end":"14:30","coach":"赵晴","remaining":0},
      {"id":"C380","title":"杠铃·入门","type":"杠铃","date":"2028-10-17","start":"06:00","end":"06:30","coach":"李岚","remaining":2},
      {"id":"C806","title":"拉伸·舒展","type":"拉伸","date":"2028-10-19","start":"08:00","end":"09:00","coach":"周宁","remaining":5},
      {"id":"C642","title":"舞蹈·入门","type":"舞蹈","date":"2028-10-17","start":"10:15","end":"11:00","coach":"林安","remaining":4},
      {"id":"C498","title":"杠铃·入门","type":"杠铃","date":"2028-10-17","start":"09:00","end":"10:00","coach":"周宁","remaining":2},
      {"id":"C248","title":"拉伸·舒展","type":"拉伸","date":"2028-10-18","start":"12:00","end":"13:00","coach":"沈禾","remaining":0},
      {"id":"C603","title":"拉伸·进阶","type":"拉伸","date":"2028-10-18","start":"09:00","end":"10:00","coach":"王珂","remaining":4},
      {"id":"C591","title":"拉伸·进阶","type":"拉伸","date":"2028-10-17","start":"09:00","end":"10:00","coach":"赵晴","remaining":2},
      {"id":"C258","title":"舞蹈·舒展","type":"舞蹈","date":"2028-10-17","start":"09:00","end":"09:45","coach":"陈星","remaining":6}
    ]
  };

  var STORAGE_KEY = "landong-" + DATA.week_id;
  var courses = DATA.courses.slice();
  var booked = [];
  var memoryStore = null;
  var storageOK = true;
  try {
    window.localStorage.setItem("__landong_test__", "1");
    window.localStorage.removeItem("__landong_test__");
  } catch (e) { storageOK = false; }

  function loadBooked() {
    var raw = null;
    if (storageOK) {
      try { raw = window.localStorage.getItem(STORAGE_KEY); } catch (e) { storageOK = false; }
    }
    if (!storageOK) raw = memoryStore;
    var ids = [];
    if (typeof raw === "string" && raw) {
      try {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          var seen = {};
          for (var i = 0; i < parsed.length; i++) {
            var v = parsed[i];
            if (typeof v !== "string" || seen[v]) continue;
            var c = byId(v);
            if (c && c.remaining > 0) { seen[v] = true; ids.push(v); }
          }
        }
      } catch (e) { ids = []; }
    }
    booked = ids;
  }

  function saveBooked() {
    var json = JSON.stringify(booked);
    if (storageOK) {
      try { window.localStorage.setItem(STORAGE_KEY, json); return; } catch (e) { storageOK = false; }
    }
    memoryStore = json;
  }

  function byId(id) {
    for (var i = 0; i < courses.length; i++) if (courses[i].id === id) return courses[i];
    return null;
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }

  function toMin(t) {
    var p = t.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  function conflictsWith(a, b) {
    if (a.date !== b.date) return false;
    var aS = toMin(a.start), aE = toMin(a.end), bS = toMin(b.start), bE = toMin(b.end);
    if (aS < bE && bS < aE) return true; // overlap
    var gap;
    if (aE <= bS) gap = bS - aE; else gap = aS - bE;
    return gap < 15;
  }

  function hasConflict(course) {
    for (var i = 0; i < booked.length; i++) {
      var other = byId(booked[i]);
      if (other && other.id !== course.id && conflictsWith(course, other)) return true;
    }
    return false;
  }

  var noticeEl = document.getElementById("notice");
  function showNotice(text, kind) {
    noticeEl.textContent = text;
    noticeEl.className = kind || "";
  }

  var listEl = document.getElementById("course-list");
  var filterEl = document.getElementById("type-filter");

  function render() {
    var t = filterEl.value;
    listEl.innerHTML = "";
    courses.forEach(function (c) {
      if (t !== "all" && c.type !== t) return;
      var card = document.createElement("div");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var left = document.createElement("div");
      var h = document.createElement("h2");
      h.textContent = c.title;
      left.appendChild(h);
      var meta = document.createElement("div");
      meta.className = "meta";
      meta.textContent = c.type + " · " + c.date + " · " + c.start + "–" + c.end + " · 教练：" + c.coach;
      left.appendChild(meta);

      var right = document.createElement("div");
      right.className = "right";
      var remainWrap = document.createElement("div");
      remainWrap.className = "remain";
      var span = document.createElement("span");
      span.setAttribute("data-remaining", "");
      span.textContent = String(currentRemaining(c));
      remainWrap.appendChild(span);
      remainWrap.appendChild(document.createTextNode(" 个剩余名额"));
      right.appendChild(remainWrap);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var b = isBooked(c.id);
      if (b) {
        btn.textContent = "已加入";
        btn.className = "booked";
        btn.disabled = true;
      } else if (currentRemaining(c) <= 0) {
        btn.textContent = "名额已满";
        btn.disabled = true;
      } else {
        btn.textContent = "加入课程";
        btn.addEventListener("click", function () { book(c.id); });
      }
      right.appendChild(btn);

      card.appendChild(left);
      card.appendChild(right);
      listEl.appendChild(card);
    });
  }

  function currentRemaining(c) {
    return c.remaining - (isBooked(c.id) ? 1 : 0);
  }

  function book(id) {
    var c = byId(id);
    if (!c) return;
    if (isBooked(id)) { showNotice("已成功锁定名额", "ok"); return; }
    if (currentRemaining(c) <= 0) { showNotice("名额已满", "err"); return; }
    if (hasConflict(c)) { showNotice("前后15分钟内已有预约", "err"); return; }
    booked.push(id);
    saveBooked();
    render();
    showNotice("已成功锁定名额", "ok");
  }

  filterEl.addEventListener("change", render);

  loadBooked();
  render();
})();
</script>
</body>
</html>

