  } catch (e) { storageOk = false; }

  function save() {
    if (!storageOk) return;
    try { window.localStorage.setItem(STORE_KEY, JSON.stringify(booked)); } catch (e) {}
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }

  function conflicts(a, b) {
    if (a.date !== b.date) return false;
    return a.start < b.end && b.start < a.end;
  }

  function hasConflict(course) {
    return booked.some(function (id) { return conflicts(byId[id], course); });
  }

  var notice = document.getElementById("notice");
  function showNotice(msg, ok) {
    notice.textContent = msg;
    notice.className = ok ? "ok" : "err";
  }

  var list = document.getElementById("course-list");
  var filter = document.getElementById("type-filter");

  function render() {
    var t = filter.value;
    list.innerHTML = "";
    courses.forEach(function (c) {
      if (t !== "all" && c.type !== t) return;
      var card = document.createElement("div");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var info = document.createElement("div");
      var h = document.createElement("h2");
      h.textContent = c.title;
      info.appendChild(h);
      var meta = document.createElement("div");
      meta.className = "meta";
      meta.textContent = "类型：" + c.type + "　日期：" + c.date + "　时间：" + c.start + "–" + c.end + "　教练：" + c.coach;
      info.appendChild(meta);
      var remWrap = document.createElement("div");
      remWrap.className = "meta";
      var rem = document.createElement("span");
      rem.setAttribute("data-remaining", "");
      rem.textContent = String(c.remaining);
      remWrap.appendChild(rem);
      remWrap.appendChild(document.createTextNode(" 个剩余名额"));
      info.appendChild(remWrap);
      card.appendChild(info);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var bk = isBooked(c.id);
      if (bk) {
        btn.textContent = "已预约";
        btn.className = "booked";
        btn.disabled = true;
      } else if (c.remaining <= 0) {
        btn.textContent = "已满员";
        btn.disabled = true;
      } else {
        btn.textContent = "预约";
        btn.addEventListener("click", function () { book(c.id); });
      }
      card.appendChild(btn);
      list.appendChild(card);
    });
  }

  function book(id) {
    var c = byId[id];
    if (isBooked(id)) return; // 重复点击：不扣名额、不重复记、不改提示
    if (c.remaining <= 0) { showNotice("该课程已满员", false); return; }
    if (hasConflict(c)) { showNotice("该时段已有预约", false); return; }
    booked.push(id);
    c.remaining -= 1;
    save();
    showNotice("预约成功", true);
    render();
  }

  filter.addEventListener("change", render);
  render();
})();
</script>
</body>
</html>

