<script>
(function () {
  "use strict";

  var SCHEDULE = {
    "week_id": "20281030",
    "venue": "岚动训练城西店",
    "courses": [
      { "id": "C387", "title": "拉伸·舒展", "type": "拉伸", "date": "2028-11-01", "start": "12:00", "end": "13:00", "coach": "赵晴", "remaining": 0 },
      { "id": "C331", "title": "杠铃·入门", "type": "杠铃", "date": "2028-10-30", "start": "17:00", "end": "18:00", "coach": "王珂", "remaining": 4 },
      { "id": "C953", "title": "舞蹈·进阶", "type": "舞蹈", "date": "2028-10-30", "start": "17:00", "end": "17:45", "coach": "陈星", "remaining": 5 },
      { "id": "C867", "title": "杠铃·力量", "type": "杠铃", "date": "2028-11-01", "start": "13:30", "end": "14:30", "coach": "沈禾", "remaining": 0 },
      { "id": "C215", "title": "舞蹈·进阶", "type": "舞蹈", "date": "2028-10-30", "start": "18:15", "end": "19:00", "coach": "林安", "remaining": 5 },
      { "id": "C779", "title": "拉伸·入门", "type": "拉伸", "date": "2028-10-31", "start": "17:00", "end": "18:00", "coach": "李岚", "remaining": 6 },
      { "id": "C869", "title": "拉伸·进阶", "type": "拉伸", "date": "2028-11-02", "start": "08:00", "end": "09:00", "coach": "王珂", "remaining": 6 },
      { "id": "C302", "title": "拉伸·力量", "type": "拉伸", "date": "2028-10-30", "start": "17:00", "end": "18:00", "coach": "沈禾", "remaining": 4 },
      { "id": "C609", "title": "杠铃·力量", "type": "杠铃", "date": "2028-10-30", "start": "06:00", "end": "06:30", "coach": "周宁", "remaining": 5 },
      { "id": "C669", "title": "舞蹈·力量", "type": "舞蹈", "date": "2028-11-02", "start": "11:00", "end": "12:00", "coach": "林安", "remaining": 7 },
      { "id": "C359", "title": "杠铃·力量", "type": "杠铃", "date": "2028-11-02", "start": "09:30", "end": "10:30", "coach": "陈星", "remaining": 2 }
    ]
  };

  var COURSES = SCHEDULE.courses;
  var BY_ID = {};
  COURSES.forEach(function (c) { BY_ID[c.id] = c; });

  var STORAGE_KEY = "landong-" + SCHEDULE.week_id;
  var MIN_GAP = 15; // 分钟

  var listEl = document.getElementById("course-list");
  var noticeEl = document.getElementById("notice");
  var filterEl = document.getElementById("type-filter");

  var memoryOnly = false;
  var booked = loadBooked();

  function loadBooked() {
    var raw = null;
    try {
      raw = localStorage.getItem(STORAGE_KEY);
    } catch (e) {
      memoryOnly = true;
      return [];
    }
    if (raw === null || raw === undefined) return [];
    var arr;
    try {
      arr = JSON.parse(raw);
    } catch (e) {
      return [];
    }
    if (!Array.isArray(arr)) return [];
    var seen = {};
    var out = [];
    for (var i = 0; i < arr.length; i++) {
      var v = arr[i];
      if (typeof v !== "string") continue;
      var c = BY_ID[v];
      if (!c) continue;              // 未知 id
      if (!(c.remaining > 0)) continue; // 初始满员的 id
      if (seen[v]) continue;         // 重复 id
      seen[v] = true;
      out.push(v);
    }
    return out;
  }

  function saveBooked() {
    if (memoryOnly) return;
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(booked));
    } catch (e) {
      memoryOnly = true; // 写不进就退回内存模式，照常预约
    }
  }

  function isBooked(id) {
    return booked.indexOf(id) !== -1;
  }

  function remainingOf(course) {
    return course.remaining - (isBooked(course.id) ? 1 : 0);
  }

  function toMin(hm) {
    var p = hm.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  // 同一天：区间重叠，或前一节结束到后一节开始不足 15 分钟 → 冲突
  function conflicts(a, b) {
    if (a.date !== b.date) return false;
    var as = toMin(a.start), ae = toMin(a.end);
    var bs = toMin(b.start), be = toMin(b.end);
    if (as < be && bs < ae) return true; // 重叠
    var gap;
    if (ae <= bs) gap = bs - ae;
    else if (be <= as) gap = as - be;
    else return true;
    return gap < MIN_GAP;
  }

  function hasConflict(course) {
    for (var i = 0; i < booked.length; i++) {
      var other = BY_ID[booked[i]];
      if (other && conflicts(course, other)) return true;
    }
    return false;
  }

  function setNotice(text, kind) {
    noticeEl.textContent = text;
    noticeEl.className = kind || "";
  }

  function buildTypes() {
    var seen = {};
    var types = [];
    COURSES.forEach(function (c) {
      if (!seen[c.type]) { seen[c.type] = true; types.push(c.type); }
    });
    types.forEach(function (t) {
      var opt = document.createElement("option");
      opt.value = t;
      opt.textContent = t;
      filterEl.appendChild(opt);
    });
  }

  function sortedCourses() {
    return COURSES.slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      if (a.start !== b.start) return a.start < b.start ? -1 : 1;
      return a.id < b.id ? -1 : 1;
    });
  }

  function render() {
    var filter = filterEl.value;
    listEl.textContent = "";
    sortedCourses().forEach(function (c) {
      if (filter !== "all" && c.type !== filter) return;
      listEl.appendChild(buildCard(c));
    });
  }

  function buildCard(c) {
    var card = document.createElement("article");
    card.className = "card";
    card.setAttribute("data-course-id", c.id);

    var h = document.createElement("h2");
    h.textContent = c.title;
    card.appendChild(h);

    var tag = document.createElement("span");
    tag.className = "type-tag";
    tag.textContent = c.type;
    card.appendChild(tag);

    var meta1 = document.createElement("p");
    meta1.className = "meta";
    meta1.textContent = "日期 " + c.date + " · " + c.start + " – " + c.end;
    card.appendChild(meta1);

    var meta2 = document.createElement("p");
    meta2.className = "meta";
    meta2.textContent = "教练：" + c.coach;
    card.appendChild(meta2);

    var meta3 = document.createElement("p");
    meta3.className = "meta";
    var label = document.createTextNode("剩余名额 ");
    var num = document.createElement("span");
    num.setAttribute("data-remaining", "");
    num.textContent = String(remainingOf(c));
    var unit = document.createTextNode(" 个");
    meta3.appendChild(label);
    meta3.appendChild(num);
    meta3.appendChild(unit);
    card.appendChild(meta3);

    var btn = document.createElement("button");
    btn.setAttribute("data-book", "");
    btn.type = "button";
    applyButtonState(btn, c);
    card.appendChild(btn);

    return card;
  }

  // 处理顺序：先已约，再满员，其余可点击（点了再看冲突）
  function applyButtonState(btn, c) {
    if (isBooked(c.id)) {
      btn.disabled = true;
      btn.textContent = "已加入";
      btn.className = "booked";
    } else if (remainingOf(c) <= 0) {
      btn.disabled = true;
      btn.textContent = "名额已满";
      btn.className = "";
    } else {
      btn.disabled = false;
      btn.textContent = "加入课程";
      btn.className = "";
    }
  }

  function findCard(id) {
    var cards = listEl.querySelectorAll("[data-course-id]");
    for (var i = 0; i < cards.length; i++) {
      if (cards[i].getAttribute("data-course-id") === id) return cards[i];
    }
    return null;
  }

  function onBookClick(card) {
    var id = card.getAttribute("data-course-id");
    var c = BY_ID[id];
    if (!c) return;

    // 已约：不重复扣名额、不重复记录、不改提示
    if (isBooked(id)) return;

    // 满员：不扣成负数（按钮本应禁用，这里兜底）
    if (remainingOf(c) <= 0) {
      setNotice("名额已满", "error");
      return;
    }

    // 时间冲突：不新增预约，不改名额
    if (hasConflict(c)) {
      setNotice("前后15分钟内已有预约", "error");
      return;
    }

    // 成功
    booked.push(id);
    saveBooked();

    var numEl = card.querySelector("[data-remaining]");
    if (numEl) numEl.textContent = String(remainingOf(c));
    var btn = card.querySelector("[data-book]");
    if (btn) applyButtonState(btn, c);

    setNotice("已成功锁定名额", "success");
  }

  listEl.addEventListener("click", function (ev) {
    var btn = ev.target.closest("[data-book]");
    if (!btn) return;
    var card = btn.closest("[data-course-id]");
    if (!card) return;
    onBookClick(card);
  });

  filterEl.addEventListener("change", render);

  buildTypes();
  render();
})();
</script>
</body>
