  var filterEl = document.getElementById("type-filter");

  // 填充类型筛选
  var types = [];
  courses.forEach(function (c) {
    if (types.indexOf(c.type) === -1) types.push(c.type);
  });
  types.forEach(function (t) {
    var o = document.createElement("option");
    o.value = t;
    o.textContent = t;
    filterEl.appendChild(o);
  });

  function render() {
    var sel = filterEl.value;
    listEl.innerHTML = "";
    courses.forEach(function (c) {
      if (sel !== "all" && c.type !== sel) return;
      var card = document.createElement("div");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var h = document.createElement("h2");
      h.textContent = c.title;
      card.appendChild(h);

      var meta = document.createElement("div");
      meta.className = "meta";
      meta.textContent = "类型：" + c.type + "　日期：" + c.date + "　时间：" + c.start + "–" + c.end + "　教练：" + c.coach;
      card.appendChild(meta);

      var leftWrap = document.createElement("div");
      leftWrap.className = "left";
      leftWrap.appendChild(document.createTextNode("剩余名额："));
      var rem = document.createElement("span");
      rem.setAttribute("data-remaining", "");
      rem.textContent = String(remainingOf(c));
      leftWrap.appendChild(rem);
      leftWrap.appendChild(document.createTextNode(" 人"));
      card.appendChild(leftWrap);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var r = remainingOf(c);
      if (isBooked(c.id)) {
        btn.textContent = "已预约";
        btn.className = "booked";
        btn.disabled = true;
      } else if (r <= 0) {
        btn.textContent = "已满员";
        btn.disabled = true;
      } else {
        btn.textContent = "预约";
        btn.addEventListener("click", function () { onBook(c.id); });
      }
      card.appendChild(btn);
      listEl.appendChild(card);
    });
  }

  function onBook(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) {
      showNotice("已预约", "err");
      return;
    }
    if (remainingOf(c) <= 0) {
      showNotice("已满员", "err");
      return;
    }
    for (var i = 0; i < booked.length; i++) {
      if (overlaps(c, byId[booked[i]])) {
        showNotice("该时段已有预约", "err");
        return;
      }
    }
    booked.push(id);
    saveBooked();
    render();
    showNotice("预约成功", "ok");
  }

  filterEl.addEventListener("change", render);

  loadBooked();
  render();
})();
</script>
</body>
