      { id:"C110", title:"舞蹈·进阶", type:"舞蹈", date:"2028-11-13", start:"10:15", end:"11:00", coach:"王珂", remaining:3 },
      { id:"C620", title:"杠铃·舒展", type:"杠铃", date:"2028-11-16", start:"09:30", end:"10:30", coach:"周宁", remaining:2 },
      { id:"C564", title:"拉伸·舒展", type:"拉伸", date:"2028-11-13", start:"09:00", end:"10:00", coach:"李岚", remaining:1 },
      { id:"C765", title:"杠铃·入门", type:"杠铃", date:"2028-11-13", start:"06:00", end:"06:30", coach:"陈星", remaining:3 },
      { id:"C681", title:"拉伸·舒展", type:"拉伸", date:"2028-11-16", start:"08:00", end:"09:00", coach:"沈禾", remaining:6 },
