  courses.forEach(function (c) { byId[c.id] = c; });

  var booked = [];
  var storageOk = true;
  var storeKey = "landong-" + DATA.week_id;

  function loadStore() {
    var raw = null;
    try {
      raw = window.localStorage.getItem(storeKey);
    } catch (e) {
      storageOk = false;
      raw = null;
    }
    if (raw === null || raw === undefined) { booked = []; return; }
    var arr;
    try {
      arr = JSON.parse(raw);
    } catch (e) {
      booked = [];
      return;
