    if (!Array.isArray(arr)) { booked = []; return; }
    var seen = {};
    var valid = [];
    arr.forEach(function (id) {
      if (typeof id !== "string") return;
      var c = byId[id];
      if (!c) return;
      if (c.remaining <= 0) return;
      if (seen[id]) return;
      seen[id] = true;
      valid.push(id);
    });
    booked = valid;
  }

  function saveStore() {
    if (!storageOk) return;
    try {
      window.localStorage.setItem(storeKey, JSON.stringify(booked));
