    return c.remaining - (isBooked(c.id) ? 1 : 0);
  }

  function toMin(hm) {
    var p = hm.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  function conflictsWith(c) {
    var s1 = toMin(c.start), e1 = toMin(c.end);
    for (var i = 0; i < booked.length; i++) {
      var o = byId[booked[i]];
      if (!o || o.date !== c.date) continue;
