      b.textContent = String(rem);
      remain.appendChild(b);
      remain.appendChild(document.createTextNode(" 个剩余名额"));
      row.appendChild(remain);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      if (isBooked(c.id)) {
        btn.textContent = "已加入";
        btn.disabled = true;
        btn.className = "booked";
      } else if (rem <= 0) {
        btn.textContent = "名额已满";
        btn.disabled = true;
      } else {
        btn.textContent = "加入课程";
        btn.addEventListener("click", function () { tryBook(c.id); });
      }
      row.appendChild(btn);

      card.appendChild(row);
      listEl.appendChild(card);
    });
  }

  function tryBook(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) return;
    if (remainingOf(c) <= 0) return;
    if (conflictsWith(c)) {
      showNotice("前后15分钟内已有预约", "err");
      return;
    }
    booked.push(id);
    saveStore();
    render();
    showNotice("已成功锁定名额", "ok");
  }

  filterEl.addEventListener("change", render);

  loadStore();
  render();
})();
</script>
</body>
