  <p>选择课程，点击“加入课程”即可锁定名额</p>
</header>
<main>
  <div class="filter-row">
    <label for="type-filter">课程类型</label>
    <select id="type-filter"></select>
  </div>
  <p id="notice" role="status" aria-live="polite"></p>
  <div id="course-list"></div>
</main>
<script>
(function () {
  var DATA = {
    "week_id": "20281127",
    "venue": "岚动训练城西店",
    "courses": [
      {"id":"C333","title":"拉伸·进阶","type":"拉伸","date":"2028-11-27","start":"09:00","end":"10:00","coach":"王珂","remaining":1},
      {"id":"C547","title":"拉伸·入门","type":"拉伸","date":"2028-11-29","start":"12:00","end":"13:00","coach":"赵晴","remaining":0},
      {"id":"C790","title":"拉伸·进阶","type":"拉伸","date":"2028-11-30","start":"08:00","end":"09:00","coach":"李岚","remaining":7},
      {"id":"C716","title":"舞蹈·力量","type":"舞蹈","date":"2028-11-27","start":"10:15","end":"11:00","coach":"周宁","remaining":3},
      {"id":"C688","title":"拉伸·进阶","type":"拉伸","date":"2028-11-28","start":"09:00","end":"10:00","coach":"陈星","remaining":6},
      {"id":"C690","title":"杠铃·入门","type":"杠铃","date":"2028-11-27","start":"09:30","end":"10:30","coach":"李岚","remaining":5},
      {"id":"C109","title":"杠铃·进阶","type":"杠铃","date":"2028-11-27","start":"06:00","end":"06:30","coach":"沈禾","remaining":3},
      {"id":"C643","title":"舞蹈·力量","type":"舞蹈","date":"2028-11-27","start":"10:10","end":"10:55","coach":"林安","remaining":2},
      {"id":"C202","title":"杠铃·舒展","type":"杠铃","date":"2028-11-29","start":"13:30","end":"14:30","coach":"王珂","remaining":0}
    ]
  };

  var courses = DATA.courses;
  var byId = {};
  courses.forEach(function (c) { byId[c.id] = c; });

  var storageKey = "landong-" + DATA.week_id;
  var booked = [];          // array of course ids
  var memStore = null;      // fallback when localStorage unavailable
  var lsOK = false;
  try {
    var t = "__t__";
    window.localStorage.setItem(t, t);
    window.localStorage.removeItem(t);
    lsOK = true;
  } catch (e) { lsOK = false; }

  function loadBooked() {
    var raw = null;
    if (lsOK) {
      try { raw = window.localStorage.getItem(storageKey); } catch (e) { raw = null; }
    } else {
      raw = memStore;
    }
    var ids = [];
    if (typeof raw === "string" && raw.length) {
      try {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          var seen = {};
          parsed.forEach(function (v) {
            if (typeof v === "string" && byId[v] && byId[v].remaining > 0 && !seen[v]) {
              seen[v] = true;
              ids.push(v);
            }
          });
        }
      } catch (e) { ids = []; }
    }
    booked = ids;
  }

  function saveBooked() {
    var s = JSON.stringify(booked);
    if (lsOK) {
      try { window.localStorage.setItem(storageKey, s); } catch (e) { memStore = s; }
    } else {
      memStore = s;
    }
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }

  function remainingOf(c) {
    var r = c.remaining;
    if (isBooked(c.id)) r = r - 1;
    return r;
  }

  function toMin(hm) {
    var p = hm.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  function conflictsWithBooked(c) {
    var s1 = toMin(c.start), e1 = toMin(c.end);
    for (var i = 0; i < booked.length; i++) {
      var o = byId[booked[i]];
      if (!o || o.date !== c.date) continue;
      var s2 = toMin(o.start), e2 = toMin(o.end);
      if (s1 < e2 + 15 && s2 < e1 + 15) return true;
    }
    return false;
  }

  var noticeEl = document.getElementById("notice");
  function showNotice(msg, kind) {
    noticeEl.textContent = msg;
    noticeEl.className = kind ? kind : "";
  }

  var listEl = document.getElementById("course-list");
  var filterEl = document.getElementById("type-filter");

  function buildFilter() {
    var types = [];
    courses.forEach(function (c) { if (types.indexOf(c.type) === -1) types.push(c.type); });
    var all = document.createElement("option");
    all.value = "all";
    all.textContent = "全部";
    filterEl.appendChild(all);
    types.forEach(function (t) {
      var o = document.createElement("option");
      o.value = t;
      o.textContent = t;
      filterEl.appendChild(o);
    });
  }

  function render() {
    var sel = filterEl.value;
    listEl.textContent = "";
    courses.forEach(function (c) {
      if (sel !== "all" && c.type !== sel) return;
      var card = document.createElement("div");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var h = document.createElement("h2");
      h.textContent = c.title;
      card.appendChild(h);

      var meta = document.createElement("p");
      meta.className = "meta";
      meta.textContent = "类型：" + c.type + "　日期：" + c.date + "　时间：" + c.start + "–" + c.end + "　教练：" + c.coach;
      card.appendChild(meta);

      var remWrap = document.createElement("p");
      remWrap.className = "meta";
      var rem = document.createElement("span");
      rem.setAttribute("data-remaining", "");
      rem.textContent = String(remainingOf(c));
      remWrap.appendChild(rem);
      remWrap.appendChild(document.createTextNode(" 个剩余名额"));
      card.appendChild(remWrap);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var r = remainingOf(c);
      if (isBooked(c.id)) {
        btn.textContent = "已加入";
        btn.className = "booked";
        btn.disabled = true;
      } else if (r <= 0) {
        btn.textContent = "名额已满";
        btn.disabled = true;
      } else {
        btn.textContent = "加入课程";
        btn.addEventListener("click", function () { onBook(c.id); });
      }
      card.appendChild(btn);
      listEl.appendChild(card);
    });
  }

  function onBook(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) { showNotice("已成功锁定名额", "ok"); return; }
    if (remainingOf(c) <= 0) { showNotice("名额已满", "err"); return; }
    if (conflictsWithBooked(c)) { showNotice("前后15分钟内已有预约", "err"); return; }
    booked.push(id);
    saveBooked();
    render();
    showNotice("已成功锁定名额", "ok");
  }

  filterEl.addEventListener("change", render);

  buildFilter();
  loadBooked();
  render();
})();
</script>
</body>
</html>

