  .meta .tag {
    display: inline-block;
    background: #eef2f6;
    border: 1px solid #d3dbe2;
    border-radius: 4px;
    padding: 0 6px;
    margin-right: 6px;
    color: #334e68;
  }
  .side { text-align: right; flex-shrink: 0; }
  .remain { font-size: 14px; color: #52606d; margin-bottom: 8px; }
