</head>
<body>
<div class="wrap">
  <header>
    <h1>晨跃健身城西店 · 本周团课预约</h1>
    <p>选择课程，点击“预约”即可完成本周预约。</p>
  </header>

  <div class="filter-row">
    <label for="type-filter">课程类型</label>
    <select id="type-filter"></select>
  </div>

  <div id="notice" role="status" aria-live="polite"></div>

  <main id="course-list"></main>
</div>

<script>
(function () {
  "use strict";

  var SCHEDULE = {
    week_id: "20281204",
    venue: "晨跃健身城西店",
    courses: [
      { id: "C423", title: "搏击·入门", type: "搏击", date: "2028-12-04", start: "17:40", end: "18:25", coach: "周宁", remaining: 6 },
      { id: "C627", title: "瑜伽·入门", type: "瑜伽", date: "2028-12-07", start: "12:30", end: "13:30", coach: "王珂", remaining: 3 },
      { id: "C217", title: "搏击·舒展", type: "搏击", date: "2028-12-04", start: "17:45", end: "18:30", coach: "沈禾", remaining: 6 },
      { id: "C332", title: "单车·力量", type: "单车", date: "2028-12-04", start: "06:00", end: "06:30", coach: "陈星", remaining: 4 },
      { id: "C158", title: "单车·进阶", type: "单车", date: "2028-12-07", start: "09:30", end: "10:30", coach: "周宁", remaining: 3 },
      { id: "C377", title: "搏击·进阶", type: "搏击", date: "2028-12-07", start: "11:00", end: "12:00", coach: "沈禾", remaining: 4 },
      { id: "C915", title: "单车·力量", type: "单车", date: "2028-12-06", start: "13:30", end: "14:30", coach: "赵晴", remaining: 0 },
      { id: "C214", title: "瑜伽·进阶", type: "瑜伽", date: "2028-12-06", start: "12:00", end: "13:00", coach: "林安", remaining: 0 },
      { id: "C686", title: "瑜伽·力量", type: "瑜伽", date: "2028-12-07", start: "08:00", end: "09:00", coach: "李岚", remaining: 1 },
      { id: "C986", title: "瑜伽·入门", type: "瑜伽", date: "2028-12-05", start: "17:00", end: "17:45", coach: "王珂", remaining: 6 },
      { id: "C312", title: "瑜伽·入门", type: "瑜伽", date: "2028-12-04", start: "17:00", end: "17:45", coach: "赵晴", remaining: 1 },
      { id: "C474", title: "单车·力量", type: "单车", date: "2028-12-04", start: "17:15", end: "18:00", coach: "李岚", remaining: 3 }
    ]
  };

  var STORAGE_KEY = "chenyue-" + SCHEDULE.week_id;

  var courses = SCHEDULE.courses.slice().sort(function (a, b) {
    if (a.date !== b.date) return a.date < b.date ? -1 : 1;
    if (a.start !== b.start) return a.start < b.start ? -1 : 1;
    return a.id < b.id ? -1 : 1;
  });

  var booked = [];          // 已预约课程 id 数组（保持预约顺序）
  var bookedSet = {};       // id -> true
  var memoryOnly = false;   // localStorage 不可用时为 true

  var listEl = document.getElementById("course-list");
  var noticeEl = document.getElementById("notice");
  var filterEl = document.getElementById("type-filter");

  function toMinutes(hhmm) {
    var p = hhmm.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  function storageAvailable() {
    try {
      var k = "__chenyue_test__";
      window.localStorage.setItem(k, "1");
      window.localStorage.removeItem(k);
      return true;
    } catch (e) {
      return false;
    }
  }

  function loadBooked() {
    if (!storageAvailable()) { memoryOnly = true; return; }
    var raw = null;
    try {
      raw = window.localStorage.getItem(STORAGE_KEY);
    } catch (e) { memoryOnly = true; return; }
    if (raw === null || raw === "") return;
    var arr;
    try {
      arr = JSON.parse(raw);
    } catch (e) { return; }
    if (!Array.isArray(arr)) return;
    var seen = {};
    var byId = {};
    courses.forEach(function (c) { byId[c.id] = c; });
    for (var i = 0; i < arr.length; i++) {
      var id = arr[i];
      if (typeof id !== "string") continue;
      var c = byId[id];
      if (!c) continue;                 // 未知 id
      if (c.remaining <= 0) continue;   // 初始满员的 id
      if (seen[id]) continue;           // 重复 id
      seen[id] = true;
      booked.push(id);
      bookedSet[id] = true;
    }
  }

  function saveBooked() {
    if (memoryOnly) return;
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(booked));
    } catch (e) { /* 写入失败时本次会话仍在内存中照常工作 */ }
  }

  function currentRemaining(c) {
    return c.remaining - (bookedSet[c.id] ? 1 : 0);
  }

  function isConflicting(c) {
    for (var i = 0; i < booked.length; i++) {
      var other = byId(booked[i]);
      if (!other || other.date !== c.date) continue;
      // 区间 [start, end)：前一节结束时刻等于后一节开始时刻不算冲突
      if (toMinutes(c.start) < toMinutes(other.end) &&
          toMinutes(other.start) < toMinutes(c.end)) {
        return true;
      }
    }
    return false;
  }

  function byId(id) {
    for (var i = 0; i < courses.length; i++) {
      if (courses[i].id === id) return courses[i];
    }
    return null;
  }

  function showNotice(text, kind) {
    noticeEl.textContent = text;
    noticeEl.className = kind || "";
  }

  function buildFilter() {
    var types = [];
    var seen = {};
    courses.forEach(function (c) {
      if (!seen[c.type]) { seen[c.type] = true; types.push(c.type); }
    });
    var allOpt = document.createElement("option");
    allOpt.value = "all";
    allOpt.textContent = "全部";
    filterEl.appendChild(allOpt);
    types.forEach(function (t) {
      var opt = document.createElement("option");
      opt.value = t;
      opt.textContent = t;
      filterEl.appendChild(opt);
    });
  }

  function buildCards() {
    courses.forEach(function (c) {
      var card = document.createElement("article");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var info = document.createElement("div");
      info.className = "info";
      var h = document.createElement("h2");
      h.textContent = c.title;
      info.appendChild(h);

      var meta1 = document.createElement("p");
      meta1.className = "meta";
      var tag = document.createElement("span");
      tag.className = "tag";
      tag.textContent = c.type;
      meta1.appendChild(tag);
      meta1.appendChild(document.createTextNode(c.date + " " + c.start + "–" + c.end));
      info.appendChild(meta1);

      var meta2 = document.createElement("p");
      meta2.className = "meta";
      meta2.textContent = "教练：" + c.coach;
      info.appendChild(meta2);

      var side = document.createElement("div");
      side.className = "side";

      var remainP = document.createElement("p");
      remainP.className = "remain";
      var remainSpan = document.createElement("span");
      remainSpan.setAttribute("data-remaining", "");
      remainSpan.textContent = String(currentRemaining(c));
      remainP.appendChild(remainSpan);
      remainP.appendChild(document.createTextNode(" 个名额"));
      side.appendChild(remainP);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      btn.type = "button";
      refreshButton(btn, c);
      side.appendChild(btn);

      card.appendChild(info);
      card.appendChild(side);
      listEl.appendChild(card);
    });
  }

  function refreshButton(btn, c) {
    if (bookedSet[c.id]) {
      btn.textContent = "已预约";
      btn.disabled = true;
    } else if (c.remaining <= 0) {
      btn.textContent = "已满员";
      btn.disabled = true;
    } else {
      btn.textContent = "预约";
      btn.disabled = false;
    }
  }

  function onBook(c) {
    // 顺序：先识别已预约，再处理满员；未约且有名额时先查冲突，再查每日上限，最后成功
    if (bookedSet[c.id]) {
      // 已预约：不重复扣名额、不重复记一次预约、不改变提示
      return;
    }
    if (c.remaining <= 0) {
      showNotice("该课程已满员", "error");
      return;
    }
    if (isConflicting(c)) {
      showNotice("该时段已有预约", "error");
      return;
    }
    // 每日上限：本页无每日预约节数上限，此检查恒通过
    booked.push(c.id);
    bookedSet[c.id] = true;
    saveBooked();

    var card = listEl.querySelector('[data-course-id="' + c.id + '"]');
    if (card) {
      var span = card.querySelector("[data-remaining]");
      if (span) span.textContent = String(currentRemaining(c));
      var btn = card.querySelector("[data-book]");
      if (btn) refreshButton(btn, c);
    }
    showNotice("预约成功", "success");
  }

  function applyFilter() {
    var v = filterEl.value;
    var cards = listEl.querySelectorAll("[data-course-id]");
    for (var i = 0; i < cards.length; i++) {
      var c = byId(cards[i].getAttribute("data-course-id"));
      cards[i].style.display = (v === "all" || c.type === v) ? "" : "none";
    }
  }

  buildFilter();
  loadBooked();
  buildCards();
  applyFilter();

  filterEl.addEventListener("change", applyFilter);

  listEl.addEventListener("click", function (ev) {
    var target = ev.target;
    if (!target || target.nodeType !== 1) return;
    var btn = target.closest ? target.closest("[data-book]") : null;
    if (!btn || btn.disabled) return;
    var card = btn.closest("[data-course-id]");
    if (!card) return;
    var c = byId(card.getAttribute("data-course-id"));
    if (c) onBook(c);
  });
})();
</script>
</body>
</html>

