  <p>本周团课预约（2028-12-11 当周）</p>
</header>
<div class="toolbar">
  <label for="type-filter">课程类型</label>
  <select id="type-filter">
    <option value="all">全部</option>
    <option value="舞蹈">舞蹈</option>
    <option value="杠铃">杠铃</option>
    <option value="拉伸">拉伸</option>
  </select>
</div>
<div id="notice" role="status" aria-live="polite"></div>
<main id="course-list"></main>
<script>
(function () {
  "use strict";
  var WEEK_ID = "20281211";
  var COURSES = [
    { id: "C198", title: "舞蹈·力量", type: "舞蹈", date: "2028-12-12", start: "09:30", end: "10:15", coach: "王珂", remaining: 4 },
    { id: "C783", title: "杠铃·舒展", type: "杠铃", date: "2028-12-12", start: "06:00", end: "06:30", coach: "林安", remaining: 3 },
    { id: "C915", title: "杠铃·舒展", type: "杠铃", date: "2028-12-14", start: "09:30", end: "10:30", coach: "陈星", remaining: 2 },
    { id: "C633", title: "拉伸·舒展", type: "拉伸", date: "2028-12-14", start: "08:00", end: "09:00", coach: "赵晴", remaining: 7 },
    { id: "C864", title: "舞蹈·舒展", type: "舞蹈", date: "2028-12-12", start: "09:25", end: "10:10", coach: "陈星", remaining: 3 },
    { id: "C417", title: "拉伸·舒展", type: "拉伸", date: "2028-12-13", start: "08:30", end: "09:15", coach: "李岚", remaining: 4 },
    { id: "C685", title: "拉伸·舒展", type: "拉伸", date: "2028-12-12", start: "08:30", end: "09:15", coach: "沈禾", remaining: 1 },
    { id: "C379", title: "拉伸·进阶", type: "拉伸", date: "2028-12-13", start: "12:00", end: "13:00", coach: "周宁", remaining: 0 },
    { id: "C423", title: "杠铃·进阶", type: "杠铃", date: "2028-12-12", start: "09:00", end: "09:45", coach: "赵晴", remaining: 6 },
    { id: "C233", title: "杠铃·入门", type: "杠铃", date: "2028-12-13", start: "13:30", end: "14:30", coach: "沈禾", remaining: 0 }
  ];
  var byId = {};
  COURSES.forEach(function (c) { byId[c.id] = c; });

  var booked = loadBooked();
  var filterEl = document.getElementById("type-filter");
  var noticeEl = document.getElementById("notice");
  var listEl = document.getElementById("course-list");

  function storageKey() { return "landong-" + WEEK_ID; }

  function loadBooked() {
    var raw;
    try { raw = window.localStorage.getItem(storageKey()); }
    catch (e) { raw = null; }
    var arr = null;
    if (typeof raw === "string" && raw.length) {
      try {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) arr = parsed;
      } catch (e) { arr = null; }
    }
    if (!arr) return [];
    var seen = {};
    var out = [];
    arr.forEach(function (v) {
      if (typeof v !== "string") return;
      var c = byId[v];
      if (!c) return;
      if (c.remaining <= 0) return;
      if (seen[v]) return;
      seen[v] = true;
      out.push(v);
    });
    return out;
  }

  function saveBooked() {
    try { window.localStorage.setItem(storageKey(), JSON.stringify(booked)); } catch (e) { /* 内存模式 */ }
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }

  function remainingOf(c) { return c.remaining - (isBooked(c.id) ? 1 : 0); }

  function toMin(hhmm) {
    var p = hhmm.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  function conflictsWith(a, b) {
    if (a.date !== b.date) return false;
    var aS = toMin(a.start), aE = toMin(a.end);
    var bS = toMin(b.start), bE = toMin(b.end);
    if (aS < bE && bS < aE) return true; // 区间重叠
    var gap;
    if (aE <= bS) gap = bS - aE; else gap = aS - bE;
    return gap < 15;
  }

  function hasConflict(course) {
    for (var i = 0; i < booked.length; i++) {
      var other = byId[booked[i]];
      if (other && other.id !== course.id && conflictsWith(course, other)) return true;
    }
    return false;
  }

  function setNotice(text, kind) {
    noticeEl.textContent = text;
    noticeEl.className = kind || "";
  }

  function render() {
    var type = filterEl.value;
    listEl.innerHTML = "";
    COURSES.forEach(function (c) {
      if (type !== "all" && c.type !== type) return;
      var card = document.createElement("section");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var h = document.createElement("h2");
      h.textContent = c.title;
      card.appendChild(h);

      var meta = document.createElement("div");
      meta.className = "meta";
      meta.innerHTML =
        "类型：<b></b><br>" +
        "日期：<b></b><br>" +
        "时间：<b></b><br>" +
        "教练：<b></b><br>";
      var bs = meta.querySelectorAll("b");
      bs[0].textContent = c.type;
      bs[1].textContent = c.date;
      bs[2].textContent = c.start + " – " + c.end;
      bs[3].textContent = c.coach;
      var remLine = document.createElement("div");
      remLine.appendChild(document.createTextNode("剩余名额："));
      var rem = document.createElement("b");
      rem.setAttribute("data-remaining", "");
      rem.textContent = String(remainingOf(c));
      remLine.appendChild(rem);
      remLine.appendChild(document.createTextNode(" 人"));
      meta.appendChild(remLine);
      card.appendChild(meta);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var r = remainingOf(c);
      if (isBooked(c.id)) {
        btn.textContent = "已加入";
        btn.className = "booked";
        btn.disabled = true;
      } else if (r <= 0) {
        btn.textContent = "名额已满";
        btn.disabled = true;
      } else {
        btn.textContent = "加入课程";
        btn.addEventListener("click", function () { book(c.id); });
      }
      card.appendChild(btn);
      listEl.appendChild(card);
    });
  }

  function book(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) {
      setNotice("已成功锁定名额", "ok"); // 重复点击不重复扣名额、不换提示
      return;
    }
    if (remainingOf(c) <= 0) {
      setNotice("名额已满", "err");
      return;
    }
    if (hasConflict(c)) {
      setNotice("前后15分钟内已有预约", "err");
      return;
    }
    booked.push(id);
    saveBooked();
    render();
    setNotice("已成功锁定名额", "ok");
  }

  filterEl.addEventListener("change", render);
  render();
  setNotice("", "");
})();
</script>
</body>
</html>

