<script>
(function () {
  var WEEK_ID = "20300909";
  var STORE_KEY = "senbu-" + WEEK_ID;
  var courses = [
    { id: "C410", title: "普拉提·入门", type: "普拉提", date: "2030-09-10", start: "08:30", end: "09:30", coach: "周宁", remaining: 2 },
