    { id: "C632", title: "普拉提·入门", type: "普拉提", date: "2030-09-11", start: "08:30", end: "09:30", coach: "林安", remaining: 6 },
    { id: "C416", title: "动感单车·力量", type: "动感单车", date: "2030-09-10", start: "09:40", end: "10:25", coach: "沈禾", remaining: 3 },
    { id: "C631", title: "核心·进阶", type: "核心", date: "2030-09-11", start: "13:30", end: "14:30", coach: "周宁", remaining: 0 }
  ];
  var byId = {};
  courses.forEach(function (c) { byId[c.id] = c; });

  var booked = [];
  var memStore = null;
  var storageOK = true;
  try {
    var t = "__senbu_test__";
    window.localStorage.setItem(t, "1");
    window.localStorage.removeItem(t);
  } catch (e) { storageOK = false; memStore = {}; }

  function readStore() {
    if (!storageOK) return memStore[STORE_KEY] || null;
    try { return window.localStorage.getItem(STORE_KEY); } catch (e) { return null; }
  }
  function writeStore(val) {
    if (!storageOK) { memStore[STORE_KEY] = val; return; }
    try { window.localStorage.setItem(STORE_KEY, val); } catch (e) {}
  }

  // 恢复预约：仅保留课表中初始余量 > 0 的合法字符串 id，去重
  var raw = readStore();
  if (typeof raw === "string" && raw !== "") {
    try {
      var parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        var seen = {};
        parsed.forEach(function (id) {
          if (typeof id === "string" && !seen[id] && byId[id] && byId[id].remaining > 0) {
            seen[id] = true; booked.push(id);
          }
        });
      }
    } catch (e) { booked = []; }
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }

  function toMin(hhmm) {
