  }

  function sameDayCount(date) {
    var n = 0;
    booked.forEach(function (id) { if (byId[id] && byId[id].date === date) n++; });
    return n;
  }

  var notice = document.getElementById("notice");
  function showNotice(text, ok) {
    notice.textContent = text;
    notice.className = ok ? "ok" : "err";
  }

  var list = document.getElementById("course-list");
  var filter = document.getElementById("type-filter");

  function render() {
    var sel = filter.value;
    list.innerHTML = "";
    courses.forEach(function (c) {
      if (sel !== "all" && c.type !== sel) return;
      var card = document.createElement("div");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);

      var info = document.createElement("div");
      var h = document.createElement("h2");
      h.textContent = c.title;
      info.appendChild(h);
      var meta = document.createElement("div");
      meta.className = "meta";
      meta.textContent = "类型：" + c.type + "　日期：" + c.date + "　时间：" + c.start + "–" + c.end + "　教练：" + c.coach;
      info.appendChild(meta);
      var remWrap = document.createElement("div");
      remWrap.className = "meta";
      var rem = document.createElement("span");
      rem.setAttribute("data-remaining", "");
      rem.textContent = String(c.remaining);
      remWrap.appendChild(rem);
      remWrap.appendChild(document.createTextNode(" 个剩余名额"));
      info.appendChild(remWrap);
      card.appendChild(info);

      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var b = isBooked(c.id);
      if (b) {
        btn.textContent = "已预订";
        btn.className = "booked";
        btn.disabled = true;
      } else if (c.remaining <= 0) {
        btn.textContent = "本课已满";
        btn.disabled = true;
      } else {
        btn.textContent = "预订团课";
        btn.addEventListener("click", function () { doBook(c.id); });
      }
      card.appendChild(btn);
      list.appendChild(card);
    });
  }

  function doBook(id) {
    var c = byId[id];
    if (!c || isBooked(id)) return; // 重复点击不重复扣名额、不改提示
    if (c.remaining <= 0) return;
    // 先检查冲突
    for (var i = 0; i < booked.length; i++) {
      if (conflicts(c, byId[booked[i]])) {
        showNotice("课程间隔不足10分钟", false);
        return;
      }
    }
    // 再检查每日上限
    if (sameDayCount(c.date) >= 2) {
      showNotice("当天最多预约2节课", false);
      return;
    }
    booked.push(id);
    c.remaining = c.remaining - 1;
    writeStore(JSON.stringify(booked));
    render();
    showNotice("预约已确认", true);
  }

  filter.addEventListener("change", render);
  render();
  showNotice("", true);
})();
</script>
</body>
</html>

