      list.appendChild(card);
    });
  }

  function book(id) {
    var c = byId[id];
    if (isBooked(id)) { show("预约已确认", true); return; }
    if (remainingOf(c) <= 0) { show("本课已满", false); return; }
    for (var i = 0; i < booked.length; i++) {
      if (conflicts(c, byId[booked[i]])) { show("课程间隔不足10分钟", false); return; }
    }
    if (dayCount(c.date) >= 2) { show("当天最多预约2节课", false); return; }
    booked.push(id);
    persist();
    render();
