<main id="list"></main>
<script>
(function () {
  "use strict";
  var WEEK_ID = "20301007";
  var COURSES = [
    { id: "C211", title: "动感单车·力量", type: "动感单车", date: "2030-10-08", start: "17:55", end: "18:40", coach: "林安", remaining: 2 },
    { id: "C597", title: "核心·力量", type: "核心", date: "2030-10-10", start: "09:30", end: "10:30", coach: "王珂", remaining: 3 },
    { id: "C659", title: "核心·舒展", type: "核心", date: "2030-10-08", start: "17:00", end: "17:45", coach: "赵晴", remaining: 4 },
    { id: "C157", title: "动感单车·力量", type: "动感单车", date: "2030-10-10", start: "11:00", end: "12:00", coach: "林安", remaining: 5 },
    { id: "C959", title: "普拉提·进阶", type: "普拉提", date: "2030-10-09", start: "17:00", end: "17:45", coach: "李岚", remaining: 2 },
    { id: "C641", title: "普拉提·力量", type: "普拉提", date: "2030-10-10", start: "08:00", end: "09:00", coach: "赵晴", remaining: 2 },
    { id: "C984", title: "普拉提·进阶", type: "普拉提", date: "2030-10-08", start: "17:00", end: "17:45", coach: "周宁", remaining: 8 },
    { id: "C431", title: "核心·入门", type: "核心", date: "2030-10-09", start: "13:30", end: "14:30", coach: "周宁", remaining: 0 },
