  ];
  var byId = {};
  COURSES.forEach(function (c) { byId[c.id] = c; });

  var booked = loadBooked();
  var filterEl = document.getElementById("type-filter");
  var noticeEl = document.getElementById("notice");
  var listEl = document.getElementById("list");

  function storageAvailable() {
    try {
      var k = "__senbu_test__";
      window.localStorage.setItem(k, "1");
      window.localStorage.removeItem(k);
      return true;
    } catch (e) { return false; }
  }
  var canStore = storageAvailable();

  function loadBooked() {
    var out = [];
    if (!canStore) return out;
    var raw = null;
    try { raw = window.localStorage.getItem("senbu-" + WEEK_ID); } catch (e) { return out; }
    if (raw === null) return out;
    var arr;
    try { arr = JSON.parse(raw); } catch (e) { return out; }
    if (!Array.isArray(arr)) return out;
    var seen = {};
    arr.forEach(function (v) {
      if (typeof v !== "string" || seen[v]) return;
      var c = byId[v];
      if (!c || c.remaining <= 0) return;
      seen[v] = true;
      out.push(v);
    });
    return out;
  }

  function saveBooked() {
    if (!canStore) return;
    try { window.localStorage.setItem("senbu-" + WEEK_ID, JSON.stringify(booked)); } catch (e) {}
  }

  function isBooked(id) { return booked.indexOf(id) !== -1; }

  function remainingOf(c) {
    return c.remaining - (isBooked(c.id) ? 1 : 0);
  }

  function toMin(hm) {
    var p = hm.split(":");
    return (+p[0]) * 60 + (+p[1]);
  }

  function conflicts(a, b) {
    if (a.date !== b.date) return false;
    var aS = toMin(a.start), aE = toMin(a.end), bS = toMin(b.start), bE = toMin(b.end);
    if (aS < bE && bS < aE) return true; // overlap
    var gap = aE <= bS ? bS - aE : aS - bE;
    return gap < 10;
  }

  function sameDayCount(date) {
    var n = 0;
    booked.forEach(function (id) { if (byId[id] && byId[id].date === date) n++; });
    return n;
  }

  function showNotice(msg, kind) {
    noticeEl.textContent = msg;
    noticeEl.className = kind || "";
  }

  function render() {
    var t = filterEl.value;
    listEl.innerHTML = "";
    COURSES.forEach(function (c) {
      if (t !== "all" && c.type !== t) return;
      var card = document.createElement("section");
      card.className = "card";
      card.setAttribute("data-course-id", c.id);
      var h = document.createElement("h2");
      h.textContent = c.title;
      card.appendChild(h);
      var meta = document.createElement("p");
      meta.className = "meta";
      meta.innerHTML =
        "类型：<b></b><br>日期：<b></b><br>时间：<b></b><br>教练：<b></b><br>剩余名额：<b data-remaining></b> 人";
      var bs = meta.querySelectorAll("b");
      bs[0].textContent = c.type;
      bs[1].textContent = c.date;
      bs[2].textContent = c.start + " – " + c.end;
      bs[3].textContent = c.coach;
      bs[4].textContent = String(remainingOf(c));
      card.appendChild(meta);
      var btn = document.createElement("button");
      btn.setAttribute("data-book", "");
      var rem = remainingOf(c);
      if (isBooked(c.id)) {
        btn.textContent = "已预订";
        btn.className = "booked";
        btn.disabled = true;
      } else if (rem <= 0) {
        btn.textContent = "本课已满";
        btn.disabled = true;
      } else {
        btn.textContent = "预订团课";
        btn.addEventListener("click", function () { book(c.id); });
      }
      card.appendChild(btn);
      listEl.appendChild(card);
    });
  }

  function book(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) { showNotice("预约已确认", "ok"); return; }
    if (remainingOf(c) <= 0) { showNotice("本课已满", "err"); return; }
    for (var i = 0; i < booked.length; i++) {
      if (conflicts(c, byId[booked[i]])) { showNotice("课程间隔不足10分钟", "err"); return; }
    }
    if (sameDayCount(c.date) >= 2) { showNotice("当天最多预约2节课", "err"); return; }
    booked.push(id);
    saveBooked();
    render();
    showNotice("预约已确认", "ok");
  }

  filterEl.addEventListener("change", render);
  render();
})();
</script>
</body>
</html>

