  var storageOk = true;
  var storeKey = 'senbu-' + WEEK_ID;
  var booked = [];

  function readStore() {
    try {
      var raw = window.localStorage.getItem(storeKey);
      if (raw === null) return [];
      var v = JSON.parse(raw);
      if (!Array.isArray(v)) return [];
      var seen = {};
      var out = [];
      v.forEach(function (id) {
