        var c = byId[id];
        if (!c || c.remaining <= 0) return;
        seen[id] = true;
        out.push(id);
      });
      return out;
    } catch (e) {
      return [];
    }
  }
  function writeStore() {
    if (!storageOk) return;
    try { window.localStorage.setItem(storeKey, JSON.stringify(booked)); } catch (e) {}
  }
  try {
    var probe = '__senbu_probe__';
    window.localStorage.setItem(probe, '1');
    window.localStorage.removeItem(probe);
  } catch (e) { storageOk = false; }
  booked = storageOk ? readStore() : [];

  function isBooked(id) { return booked.indexOf(id) !== -1; }
  function remainingOf(c) { return c.remaining - (isBooked(c.id) ? 1 : 0); }

  function toMin(t) {
    var p = t.split(':');
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }
  function conflicts(a, b) {
    if (a.date !== b.date) return false;
    var aS = toMin(a.start), aE = toMin(a.end), bS = toMin(b.start), bE = toMin(b.end);
    if (aS < bE && bS < aE) return true;
    var gap;
    if (aE <= bS) gap = bS - aE; else gap = aS - bE;
    return gap < 10;
  }
  function dayCount(date) {
    var n = 0;
    booked.forEach(function (id) { if (byId[id] && byId[id].date === date) n++; });
    return n;
  }

  var notice = document.getElementById('notice');
  function showNotice(text, ok) {
    notice.textContent = text;
    notice.className = ok ? 'ok' : 'err';
