      if (isB) {
        btn.textContent = '已预订';
        btn.className = 'booked';
        btn.disabled = true;
      } else if (rem <= 0) {
        btn.textContent = '本课已满';
        btn.disabled = true;
      } else {
        btn.textContent = '预订团课';
        btn.addEventListener('click', function () { attemptBook(c.id); });
      }
      card.appendChild(btn);
      list.appendChild(card);
    });
  }

  function attemptBook(id) {
    var c = byId[id];
    if (!c) return;
    if (isBooked(id)) { showNotice('预约已确认', true); return; }
    if (remainingOf(c) <= 0) { showNotice('本课已满', false); return; }
    for (var i = 0; i < booked.length; i++) {
      if (conflicts(c, byId[booked[i]])) { showNotice('课程间隔不足10分钟', false); return; }
    }
    if (dayCount(c.date) >= 2) { showNotice('当天最多预约2节课', false); return; }
    booked.push(id);
    writeStore();
    render();
    showNotice('预约已确认', true);
  }

  filter.addEventListener('change', render);
  render();
})();
</script>
