<script>
(function(){
  "use strict";
  var DATA={"week_id":"20301028","venue":"森步运动湖畔店","courses":[{"id":"C803","title":"核心·力量","type":"核心","date":"2030-10-30","start":"13:30","end":"14:30","coach":"王珂","remaining":0},{"id":"C125","title":"核心·舒展","type":"核心","date":"2030-10-28","start":"09:30","end":"10:15","coach":"林安","remaining":6},{"id":"C500","title":"动感单车·进阶","type":"动感单车","date":"2030-10-28","start":"09:55","end":"10:40","coach":"沈禾","remaining":5},{"id":"C690","title":"核心·力量","type":"核心","date":"2030-10-28","start":"06:00","end":"06:30","coach":"李岚","remaining":3},{"id":"C647","title":"普拉提·入门","type":"普拉提","date":"2030-10-31","start":"08:00","end":"09:00","coach":"林安","remaining":8},{"id":"C508","title":"普拉提·入门","type":"普拉提","date":"2030-10-29","start":"09:00","end":"09:45","coach":"赵晴","remaining":3},{"id":"C976","title":"动感单车·入门","type":"动感单车","date":"2030-10-31","start":"11:00","end":"12:00","coach":"沈禾","remaining":6},{"id":"C109","title":"普拉提·入门","type":"普拉提","date":"2030-10-30","start":"12:00","end":"13:00","coach":"周宁","remaining":0},{"id":"C453","title":"普拉提·入门","type":"普拉提","date":"2030-10-28","start":"09:00","end":"09:45","coach":"王珂","remaining":1},{"id":"C207","title":"核心·舒展","type":"核心","date":"2030-10-31","start":"09:30","end":"10:30","coach":"陈星","remaining":2},{"id":"C697","title":"动感单车·进阶","type":"动感单车","date":"2030-10-28","start":"09:50","end":"10:35","coach":"陈星","remaining":4}]};
  var courses=DATA.courses, byId={};
  courses.forEach(function(c){byId[c.id]=c;});
  var KEY="senbu-"+DATA.week_id;
  var booked={}; // id -> true
  var memOnly=false;
  var notice=document.getElementById("notice");
  var list=document.getElementById("list");
  var filter=document.getElementById("type-filter");

  function toMin(t){var p=t.split(":");return (+p[0])*60+(+p[1]);}
  function conflicts(a,b){
    if(a.date!==b.date) return false;
    var s1=toMin(a.start),e1=toMin(a.end),s2=toMin(b.start),e2=toMin(b.end);
    if(s1<e2 && s2<e1) return true;           // 区间重叠
    var gap=s2>=e1 ? s2-e1 : s1-e2;           // 前一节结束到后一节开始的间隔
    return gap<10;
  }
  function sameDayCount(date,excludeId){
    var n=0;
    for(var id in booked){ if(booked[id]&&id!==excludeId&&byId[id]&&byId[id].date===date) n++; }
    return n;
  }
  function remainingOf(c){ return c.remaining - (booked[c.id]?1:0); }

  function showNotice(text,ok){
    notice.textContent=text;
    notice.className=ok?"ok":"err";
  }

  function save(){
    if(memOnly) return;
    try{ localStorage.setItem(KEY,JSON.stringify(Object.keys(booked).filter(function(id){return booked[id];}))); }
    catch(e){ memOnly=true; }
