    if(raw===null||raw===undefined) return;
    var arr;
    try{ arr=JSON.parse(raw); }catch(e){ return; }
    if(!Array.isArray(arr)) return;
    var seen={};
    arr.forEach(function(v){
      if(typeof v!=="string"||seen[v]) return;
      var c=byId[v];
      if(!c) return;
      if(c.remaining<=0) return;      // 忽略满员 id
      seen[v]=true; booked[v]=true;   // 规则保证合法 id 之间不违反时间/每日上限
    });
  }

  function buildFilter(){
    var types=[],seen={};
    courses.forEach(function(c){ if(!seen[c.type]){seen[c.type]=true;types.push(c.type);} });
    types.forEach(function(t){
      var o=document.createElement("option");
      o.value=t; o.textContent=t;
      filter.appendChild(o);
    });
  }

  function render(){
    var sel=filter.value;
    list.innerHTML="";
    courses.forEach(function(c){
      if(sel!=="all"&&c.type!==sel) return;
      var rem=remainingOf(c);
      var isBooked=!!booked[c.id];
      var li=document.createElement("li");
      li.className="card";
      li.setAttribute("data-course-id",c.id);
      var left=document.createElement("div");
