      var remEl=document.createElement("span");
      remEl.setAttribute("data-remaining","");
      remEl.textContent=String(rem);
      remWrap.appendChild(remEl);
      remWrap.appendChild(document.createTextNode(" 个名额"));
      var btn=document.createElement("button");
      btn.setAttribute("data-book","");
      btn.type="button";
      if(isBooked){
        btn.textContent="已预订"; btn.className="booked"; btn.disabled=true;
      }else if(rem<=0){
        btn.textContent="本课已满"; btn.disabled=true;
      }else{
        btn.textContent="预订团课";
        btn.addEventListener("click",function(){tryBook(c);});
      }
      side.appendChild(remWrap); side.appendChild(btn);
      li.appendChild(left); li.appendChild(side);
      list.appendChild(li);
    });
  }

  function refreshCard(c){
    var li=list.querySelector('[data-course-id="'+c.id+'"]');
    if(!li) return;
    var remEl=li.querySelector("[data-remaining]");
    if(remEl) remEl.textContent=String(remainingOf(c));
    var btn=li.querySelector("[data-book]");
    if(btn){
      if(booked[c.id]){ btn.textContent="已预订"; btn.className="booked"; btn.disabled=true; }
      else if(remainingOf(c)<=0){ btn.textContent="本课已满"; btn.disabled=true; }
    }
  }

  function tryBook(c){
    if(booked[c.id]){ showNotice("预约已确认",true); return; }         // 重复点击不改提示
    if(remainingOf(c)<=0){ showNotice("本课已满",false); return; }
