      { "id": "C795", "title": "普拉提·进阶", "type": "普拉提", "date": "2030-11-12", "start": "08:30", "end": "09:15", "coach": "周宁", "remaining": 5 },
      { "id": "C898", "title": "普拉提·入门", "type": "普拉提", "date": "2030-11-13", "start": "12:00", "end": "13:00", "coach": "陈星", "remaining": 0 },
      { "id": "C252", "title": "核心·进阶", "type": "核心", "date": "2030-11-11", "start": "08:45", "end": "09:30", "coach": "王珂", "remaining": 6 },
      { "id": "C919", "title": "普拉提·进阶", "type": "普拉提", "date": "2030-11-14", "start": "08:00", "end": "09:00", "coach": "王珂", "remaining": 5 },
      { "id": "C760", "title": "核心·入门", "type": "核心", "date": "2030-11-13", "start": "13:30", "end": "14:30", "coach": "林安", "remaining": 0 },
      { "id": "C212", "title": "动感单车·进阶", "type": "动感单车", "date": "2030-11-14", "start": "11:00", "end": "12:00", "coach": "赵晴", "remaining": 1 },
      { "id": "C385", "title": "核心·舒展", "type": "核心", "date": "2030-11-14", "start": "09:30", "end": "10:30", "coach": "李岚", "remaining": 5 }
    ]
  };

  var courses = SCHEDULE.courses;
  var byId = {};
  courses.forEach(function (c) { byId[c.id] = c; });

  var KEY = "senbu-" + SCHEDULE.week_id;
  var booked = new Set();

  function toMinutes(t) {
    var p = t.split(":");
    return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
  }

  // 同一天才调用：区间重叠，或前一节结束到后一节开始不足 10 分钟即冲突
  function isConflict(a, b) {
    var as = toMinutes(a.start), ae = toMinutes(a.end);
    var bs = toMinutes(b.start), be = toMinutes(b.end);
    if (as < be && bs < ae) return true; // 重叠
    var gap;
    if (bs >= ae) gap = bs - ae;
    else if (as >= be) gap = as - be;
    else gap = 0;
    return gap < 10;
  }

  function loadBooked() {
    var arr = null;
    try {
      var raw = window.localStorage.getItem(KEY);
      if (raw !== null && raw !== undefined) {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) arr = parsed;
      }
    } catch (e) {
      arr = null;
    }
    var set = new Set();
    if (arr) {
      for (var i = 0; i < arr.length; i++) {
        var v = arr[i];
        if (typeof v !== "string") continue;
        var c = byId[v];
        if (!c) continue;            // 未知 id
        if (c.remaining <= 0) continue; // 满员 id
        set.add(v);                  // Set 自动去重
      }
    }
    return set;
  }

  function saveBooked() {
    try {
      window.localStorage.setItem(KEY, JSON.stringify(Array.from(booked)));
    } catch (e) {
      // 存储不可用：仅内存预约，不报错
    }
  }

  function currentRemaining(c) {
    return c.remaining - (booked.has(c.id) ? 1 : 0);
  }

  var noticeEl = document.getElementById("notice");
  function setNotice(text) {
    noticeEl.textContent = text;
  }

  var listEl = document.getElementById("course-list");

  function buildCard(c) {
    var card = document.createElement("article");
    card.className = "card";
    card.setAttribute("data-course-id", c.id);

    var h = document.createElement("h2");
    h.textContent = c.title;
    card.appendChild(h);

    function meta(label, text) {
      var p = document.createElement("p");
      p.className = "meta";
      var s = document.createElement("strong");
      s.textContent = label;
      p.appendChild(s);
      p.appendChild(document.createTextNode(text));
      return p;
    }
    card.appendChild(meta("类型：", c.type));
    card.appendChild(meta("日期：", c.date));
    card.appendChild(meta("时间：", c.start + " – " + c.end));
    card.appendChild(meta("教练：", c.coach));

    var pRem = document.createElement("p");
    pRem.className = "meta";
    var s1 = document.createElement("strong");
    s1.textContent = "剩余名额：";
    var spanRem = document.createElement("span");
    spanRem.setAttribute("data-remaining", "");
    pRem.appendChild(s1);
    pRem.appendChild(spanRem);
    pRem.appendChild(document.createTextNode(" 位"));
    card.appendChild(pRem);

    var btn = document.createElement("button");
    btn.type = "button";
    btn.setAttribute("data-book", "");
    btn.addEventListener("click", function () { onBook(c.id); });
    card.appendChild(btn);

    return card;
  }

  function renderCourse(c) {
    var card = listEl.querySelector('article[data-course-id="' + c.id + '"]');
    if (!card) return;
    var spanRem = card.querySelector("[data-remaining]");
    spanRem.textContent = String(currentRemaining(c));
    var btn = card.querySelector("[data-book]");
    if (booked.has(c.id)) {
      btn.textContent = "已预订";
      btn.disabled = true;
    } else if (currentRemaining(c) <= 0) {
      btn.textContent = "本课已满";
      btn.disabled = true;
    } else {
      btn.textContent = "预订团课";
      btn.disabled = false;
    }
  }

  function renderAll() {
    courses.forEach(renderCourse);
  }

  function onBook(id) {
    var c = byId[id];
    if (!c) return;
    // 先识别已预约的课：重复点击不扣名额、不记预约、不改提示
    if (booked.has(id)) return;
    // 再处理满员（按钮通常已禁用，防御处理）
    if (c.remaining <= 0) {
      setNotice("本课已满");
      return;
    }
    // 未约且有名额：先查冲突
    var conflict = false;
    booked.forEach(function (bid) {
      var b = byId[bid];
      if (b && b.date === c.date && isConflict(b, c)) conflict = true;
    });
    if (conflict) {
      setNotice("课程间隔不足10分钟");
      return;
    }
    // 再查每日上限
    var count = 0;
    booked.forEach(function (bid) {
      if (byId[bid] && byId[bid].date === c.date) count++;
    });
    if (count >= 2) {
      setNotice("当天最多预约2节课");
      return;
    }
    // 成功
    booked.add(id);
    saveBooked();
    renderCourse(c);
    setNotice("预约已确认");
  }

  // 初始化卡片
  courses.forEach(function (c) { listEl.appendChild(buildCard(c)); });

  // 类型筛选（不清除预约、不改变名额）
  var sel = document.getElementById("type-filter");
  var seenTypes = [];
  courses.forEach(function (c) {
    if (seenTypes.indexOf(c.type) === -1) seenTypes.push(c.type);
  });
  seenTypes.forEach(function (t) {
    var opt = document.createElement("option");
    opt.value = t;
    opt.textContent = t;
    sel.appendChild(opt);
  });
  sel.addEventListener("change", function () {
    var val = sel.value;
    Array.prototype.forEach.call(listEl.children, function (card) {
      var c = byId[card.getAttribute("data-course-id")];
      card.hidden = !(val === "all" || c.type === val);
    });
  });

  // 恢复本周预约并渲染
  booked = loadBooked();
  saveBooked();
  renderAll();
  setNotice("");
})();
</script>
</body>
</html>
